theorem.raw:
\label{ball1point}
Let $\{\boldsymbol{x}_1, \ldots , \boldsymbol{x}_M\}$ be a set of $M$  i.i.d. random points  from the equidustribution in the unit ball $\mathbb{B}_n$, $0<r<1$. Then
\begin{equation}\label{Eq:ball1}
\begin{split}
&\mathbf{P}\left(\|\boldsymbol{x}_M\|>r \mbox{ and } \left(\boldsymbol{x}_i,\frac{\boldsymbol{x}_M}{\| \boldsymbol{x}_M\| }\right)<r \mbox{ for all } i\neq M \right)\\
&   \geq 1-r^n-0.5(M-1) \rho^{n};
\end{split}
\end{equation}
\begin{equation}\label{Eq:ballM}
\begin{split}
&\mathbf{P}\left(\|\boldsymbol{x}_j\|>r  \mbox{ and } \left(\boldsymbol{x}_i,\frac{\boldsymbol{x}_j}{\| \boldsymbol{x}_j\|}\right)<r \mbox{ for all } i,j, \, i\neq j\right)\\
&   \geq  1-Mr^n-0.5M(M-1)\rho^{n};
\end{split}
\end{equation}
\begin{equation}\label{Eq:ballMangle}
\begin{split}
&\mathbf{P}\left(\|\boldsymbol{x}_j\|>r  \mbox{ and } \left(\frac{\boldsymbol{x}_i}{\| \boldsymbol{x}_i\|},\frac{\boldsymbol{x}_j}{\| \boldsymbol{x}_j\|}\right)<r \mbox{ for all } i,j, \,i\neq j\right)\\
&  \geq  1-Mr^n-M(M-1)\rho^{n}.
\end{split}
\end{equation}

\label{cube} Let  $\{\boldsymbol{x}_1, \ldots , \boldsymbol{x}_M\}$ be i.i.d. random points  from the product distribution in a unit cube, $0< \delta <2/3$. Then
\begin{equation}\label{Eq:cube1}
\begin{split}
&\mathbf{P}\left(1-\delta  \leq \frac{\|\boldsymbol{x}_j-\overline{\boldsymbol{x}}\|^2}{R^2_0}\leq 1+\delta \mbox{ and } \right. \\
& \left.
\left(\frac{\boldsymbol{x}_i-\overline{\boldsymbol{x}}}{R_0},\frac{\boldsymbol{x}_M-\overline{\boldsymbol{x}}}{\| \boldsymbol{x}_M-\overline{\boldsymbol{x}}\| }\right)<\sqrt{1-\delta} \mbox{ for all } i,j, \, i\neq M \right)\\
&\geq 1- 2M\exp \left(-2\delta^2 R_0^4/n \right) -(M-1)\exp \left(-2R_0^4(2-3 \delta)^2/n\right);
\end{split}
\end{equation}
\begin{equation}\label{Eq:cube2}
\begin{split}
&\mathbf{P}\left(1-\delta  \leq \frac{\|\boldsymbol{x}_j-\overline{\boldsymbol{x}}\|^2}{R^2_0}\leq 1+\delta \mbox{ and } \right. \\
&\left.
\left(\frac{\boldsymbol{x}_i-\overline{\boldsymbol{x}}}{R_0},\frac{\boldsymbol{x}_j-\overline{\boldsymbol{x}}}{\| \boldsymbol{x}_j-\overline{\boldsymbol{x}}\| }\right)<\sqrt{1-\delta} \mbox{ for all } i,j, \, i\neq j \right)\\
&\geq 1- 2M\exp \left(-2\delta^2 R_0^4/n \right) -M(M-1)\exp \left(-2R_0^4(2-3 \delta)^2/n\right)
\end{split}
\end{equation}

\label{CascadeSep}
Let $S=\{\boldsymbol{x}_1, \ldots , \boldsymbol{x}_M\}$ be a set of $M$  i.i.d. random points  from the equidustribution in the unit ball $\mathbb{B}_n$, $0<r<1$. Then
\begin{equation}\label{Eq:ball1n}
\begin{split}
&\mathbf{P} \left(\|\boldsymbol{x}_M\|>r \, \&\,  \left(\boldsymbol{x}_i,\frac{\boldsymbol{x}_M}{\| \boldsymbol{x}_M\| }\right)<r
 \mbox{ for at least } M\!-\!n \mbox{ points }  \boldsymbol{x}_i\in S\right)  \\
& \geq (1-r^n)(1-0.5\rho^{n})^{M-1} \\
&\times  \left(1-\frac{1}{n!}\left(\frac{0.5(M-n)\rho^{n}}{1-0.5\rho^{n}}\right)^n\right) \exp{\left[\frac{0.5(M-n)\rho^{n}}{1-0.5\rho^{n}}\right]},
\end{split}
\end{equation}

corollary.raw:
Let  $\{\boldsymbol{x}_1, \ldots , \boldsymbol{x}_M\}$ be i.i.d. random points  from the product distribution in a unit cube and $0<\vartheta<1$. If
  \begin{equation}\label{SampleSizeCube1}
 M<\frac{1}{3}\vartheta \exp\left(0.5 n\sigma_0^4 \right),
 \end{equation}
  then with probability $p>1-\vartheta$
\[
\begin{split}
&  0.5\leq \frac{\|\boldsymbol{x}_j-\overline{\boldsymbol{x}}\|^2}{R_0^2} \leq 1.5 \mbox{ and }
\left(\frac{\boldsymbol{x}_i-\overline{\boldsymbol{x}}}{R_0},\frac{\boldsymbol{x}_M-\overline{\boldsymbol{x}}}{\| \boldsymbol{x}_M-\overline{\boldsymbol{x}}\|}\right)<\frac{\sqrt{2}}{2} \\
&\mbox{  for all } i,j, i \neq M.
\end{split}
\]
 If
  \begin{equation}\label{SampleSizeCube2}
(M+1)^2<\frac{1}{3}\vartheta \exp\left(0.5 n\sigma_0^4 \right),
 \end{equation}
   then with probability $p>1-\vartheta$

\[
\begin{split}
&0.5\leq \frac{\|\boldsymbol{x}_j-\overline{\boldsymbol{x}}\|^2}{R_0^2} \leq 1.5 \mbox{ and }
\left(\frac{\boldsymbol{x}_i-\overline{\boldsymbol{x}}}{R_0},\frac{\boldsymbol{x}_j-\overline{\boldsymbol{x}}}{\| \boldsymbol{x}_j-\overline{\boldsymbol{x}}\|}\right)<\frac{\sqrt{2}}{2} \\
& \mbox{ for all }i,j, i\neq j.
\end{split}
\]
In particular, if inequality (\ref{SampleSizeCube2}) holds then the set   $\{\boldsymbol{x}_1, \ldots , \boldsymbol{x}_M\}$ is linearly separable with probability $p>1-\vartheta$.

